insert into public.communities (slug, name, summary, lifestyle, schools, transport, avg_price_per_sqft, est_yield, price_change_12m, lat, lng, waterfront, dld_areas, published) values
  ('dubai-marina', 'Dubai Marina', '{"en":"A waterfront district of towers around a 3 km canal, with strong short-let demand all year."}'::jsonb, '{"en":"Marina walk, beach clubs at JBR, yacht berths and hundreds of restaurants within walking distance."}'::jsonb, '{"en":"Several international and British-curriculum schools within a 10–15 minute drive."}'::jsonb, '{"en":"Metro, tram and direct access to Sheikh Zayed Road."}'::jsonb, 2050, 0.066, 0.11, 25.0805, 55.1403, true, array['Marsa Dubai']::text[], true),
  ('downtown-dubai', 'Downtown Dubai', '{"en":"The address of Burj Khalifa and Dubai Mall: Dubai’s most recognised skyline and a magnet for global buyers."}'::jsonb, '{"en":"Dubai Mall, the Opera district, the fountain boulevard and five-star dining."}'::jsonb, '{"en":"International schools across nearby Business Bay and Al Safa."}'::jsonb, '{"en":"Two metro stations and fast links to DIFC and the airport."}'::jsonb, 2950, 0.058, 0.09, 25.1972, 55.2744, false, array['Burj Khalifa']::text[], true),
  ('palm-jumeirah', 'Palm Jumeirah', '{"en":"The island landmark: beachfront villas and signature residences with very limited new supply."}'::jsonb, '{"en":"Private beaches, resort hotels, fine dining and the Palm boardwalk."}'::jsonb, '{"en":"Top international schools in Al Sufouh and Al Barsha, 10–20 minutes away."}'::jsonb, '{"en":"Palm Monorail and quick access to Sheikh Zayed Road."}'::jsonb, 4100, 0.052, 0.14, 25.1124, 55.139, true, array['Palm Jumeirah']::text[], true),
  ('business-bay', 'Business Bay', '{"en":"Canal-side towers next to Downtown, popular with professionals and investors seeking higher yields."}'::jsonb, '{"en":"Dubai Water Canal promenade, hotels, offices and cafés."}'::jsonb, '{"en":"International schools in Al Safa and Al Quoz within a short drive."}'::jsonb, '{"en":"Business Bay metro and direct access to Al Khail and Sheikh Zayed Road."}'::jsonb, 2250, 0.068, 0.1, 25.185, 55.265, true, array['Business Bay']::text[], true),
  ('dubai-hills-estate', 'Dubai Hills Estate', '{"en":"A master-planned green community with villas, apartments, a golf course and a central park."}'::jsonb, '{"en":"Dubai Hills Mall, the 18-hole golf course, parks and cycling trails."}'::jsonb, '{"en":"Several British and IB schools inside or next to the community."}'::jsonb, '{"en":"Al Khail Road links to Downtown in about 15 minutes."}'::jsonb, 2350, 0.056, 0.12, 25.1036, 55.2393, false, array['Hadaeq Sheikh Mohammed Bin Rashid']::text[], true),
  ('jumeirah-village-circle', 'Jumeirah Village Circle', '{"en":"An affordable, family-friendly circle of low-rise buildings and townhouses with some of Dubai’s highest yields."}'::jsonb, '{"en":"Community parks, Circle Mall and neighbourhood cafés."}'::jsonb, '{"en":"Nursery and primary schools inside JVC, more in Al Barsha South."}'::jsonb, '{"en":"Al Khail Road and Hessa Street connect to Marina and Downtown."}'::jsonb, 1250, 0.078, 0.13, 25.06, 55.206, false, array['Al Barsha South Fourth']::text[], true),
  ('dubai-creek-harbour', 'Dubai Creek Harbour', '{"en":"A waterfront city next to the Ras Al Khor wildlife sanctuary, with skyline views and new launches."}'::jsonb, '{"en":"Creek Marina, the boardwalk and parkland facing the Downtown skyline."}'::jsonb, '{"en":"International schools in nearby Nad Al Sheba and Festival City."}'::jsonb, '{"en":"Ras Al Khor Road, with a planned metro extension."}'::jsonb, 2300, 0.064, 0.1, 25.196, 55.346, true, array['Al Khairan First']::text[], true);
