  ('golden-visa-property-rules', '{"en":"The Golden Visa through property: the rules"}'::jsonb, '{"en":"Who qualifies, how off-plan and mortgaged properties are treated, and how to apply."}'::jsonb, '[{"en":"Sample article used while the site is built."}]'::jsonb, 'guides', 'Buildcaps Research', 6, true, '2026-08-20'),
